// Show the pull request for the session's branch in the prompt status row as
// "#123", colored by state the way GitHub does: green open, purple merged, red
// closed, grey draft. Click it to open the PR in the browser.
//
// Renders into the session_prompt_footer slot, which only exists in the
// local opencode build (feat/tui-prompt-footer-slot). On a host without the
// slot this registers and simply never shows.
//
// Which PR: the newest one the chat itself created or merged (read from its
// shell calls; the muted name before the badge is that PR's branch),
// else the PR of the newest existing worktree the chat worked in, else the PR
// of the session directory's branch. The branch lookup is
// `gh pr list --head <branch>`, because `gh pr view` without a number misses
// PRs opened from a fork unless the branch tracks the fork remote. Refreshed when the
// session goes idle (an agent turn may have pushed or opened the PR) and on a
// timer for state changes made elsewhere (merged on GitHub, say).
//
// Options (tui.json -> ["./tui-plugins/pr-footer.js", { ... }]):
//   interval_ms  background refresh period (default 60000)

import { createElement, createTextNode, effect, insert, insertNode, setProp, createComponent } from "@opentui/solid"
import { createEffect, createSignal, onCleanup, Show } from "solid-js"
import { execFile } from "node:child_process"
import { promisify } from "node:util"

const run = promisify(execFile)

const DEFAULTS = { interval_ms: 60_000 }

// Several TUIs can sit on the same branch; one gh call serves them all.
const CACHE_MS = 15_000
const cache = new Map()

const SKIP_BRANCHES = new Set(["HEAD", "main", "master", "dev", "develop"])

async function branchOf(dir) {
  const { stdout } = await run("git", ["-C", dir, "rev-parse", "--abbrev-ref", "HEAD"])
  return stdout.trim()
}

// A session lives at the repo root, but its work usually happens in a worktree
// that is deleted after the merge, and the root can sit on any stale branch.
// So the root's branch says nothing about the PR a chat made. Read the chat's
// own tool calls instead: the newest `gh pr create/merge/...` wins, then the
// newest existing linked worktree it worked in, and only then the root's branch.
const PR_COMMAND = /\bgh\s+pr\s+(?:create|merge|ready|close|reopen|edit)\b/
const PR_URL = /github\.com\/([^/\s]+\/[^/\s]+)\/pull\/(\d+)/
const PR_ARG = /\bgh\s+pr\s+(?:merge|ready|close|reopen|edit)\s+(?:\S+\/pull\/)?(\d+)/

function commandDir(input) {
  if (typeof input?.workdir === "string" && input.workdir) return input.workdir
  const cd = /^\s*cd\s+("[^"]+"|'[^']+'|[^\s;&|]+)/.exec(input?.command ?? "")
  return cd?.[1].replace(/^["']|["']$/g, "")
}

// Newest first: [{ dir, pr?: { repo?, number } }] for every shell call that
// either ran in a directory or touched a pull request.
export function scan(messages) {
  const events = []
  for (const message of messages) {
    if (message.type !== "assistant") continue
    for (const part of message.content ?? []) {
      const input = part.type === "tool" && part.name === "shell" ? part.state?.input : undefined
      if (typeof input?.command !== "string") continue
      const dir = commandDir(input)
      const output = (part.state.content ?? []).map((item) => item.text ?? "").join("\n")
      const url = PR_COMMAND.test(input.command) ? PR_URL.exec(output) ?? PR_URL.exec(input.command) : undefined
      const number = url?.[2] ?? (PR_COMMAND.test(input.command) ? PR_ARG.exec(input.command)?.[1] : undefined)
      events.push({ dir, pr: number ? { repo: url?.[1], number: Number(number) } : undefined })
    }
  }
  return events.reverse()
}

async function isLinkedWorktree(dir) {
  if (!dir) return false
  const [git, common] = await Promise.all(
    ["--git-dir", "--git-common-dir"].map((flag) =>
      run("git", ["-C", dir, "rev-parse", "--path-format=absolute", flag]).then(({ stdout }) => stdout.trim()),
    ),
  ).catch(() => [])
  return Boolean(git && git !== common)
}

function cached(key, load) {
  const hit = cache.get(key)
  if (hit && Date.now() - hit.at < CACHE_MS) return hit.value
  const value = load().catch(() => undefined)
  cache.set(key, { at: Date.now(), value })
  return value
}

const pull = (pr) => ({
  branch: pr.headRefName,
  number: pr.number,
  url: pr.url,
  state: pr.isDraft && pr.state === "OPEN" ? "draft" : pr.state.toLowerCase(),
})

const byNumber = (root, found) =>
  cached(`${root}\0#${found.repo ?? ""}${found.number}`, () =>
    run(
      "gh",
      ["pr", "view", String(found.number), ...(found.repo ? ["--repo", found.repo] : []), "--json", "number,url,state,isDraft,headRefName"],
      { cwd: root, timeout: 15_000 },
    ).then(({ stdout }) => pull(JSON.parse(stdout))),
  )

const byBranch = async (dir) => {
  const branch = await branchOf(dir).catch(() => "")
  if (!branch || SKIP_BRANCHES.has(branch)) return undefined
  return cached(`${dir}\0${branch}`, () =>
    run("gh", ["pr", "list", "--head", branch, "--state", "all", "--limit", "1", "--json", "number,url,state,isDraft,headRefName"], {
      cwd: dir,
      timeout: 15_000,
    }).then(({ stdout }) => {
      const pr = JSON.parse(stdout)[0]
      return pr ? pull(pr) : undefined
    }),
  )
}

// The TUI only holds the newest messages of a long chat, so the call that made
// the PR can scroll out of view; remember it for as long as this TUI is open.
const remembered = new Map()

async function lookup(root, messages, sessionID) {
  for (const event of scan(messages)) {
    if (event.pr) {
      const pr = await byNumber(root, event.pr)
      if (pr) {
        remembered.set(sessionID, event.pr)
        return pr
      }
    }
    if (await isLinkedWorktree(event.dir)) return byBranch(event.dir)
  }
  const earlier = remembered.get(sessionID)
  return (earlier && (await byNumber(root, earlier))) || byBranch(root)
}

export { lookup }

function PrFooter(props) {
  const { api, options } = props
  const [pr, setPr] = createSignal()
  let generation = 0

  const refresh = async (sessionID) => {
    const mine = ++generation
    const root = api.state.session.get(sessionID)?.directory ?? api.state.path.directory
    const value = await lookup(root, api.state.session.messages?.(sessionID) ?? [], sessionID)
    if (mine === generation) setPr(value)
  }

  createEffect(() => {
    const sessionID = props.sessionID
    setPr(undefined)
    void refresh(sessionID)
  })

  const timer = setInterval(() => void refresh(props.sessionID), options.interval_ms)
  const off = api.event.on("session.idle", (event) => {
    if (event.properties?.sessionID !== props.sessionID) return
    cache.clear()
    void refresh(props.sessionID)
  })
  onCleanup(() => {
    generation++
    clearInterval(timer)
    off()
  })

  // GitHub's merged purple; themes have no color that reliably reads as purple.
  const MERGED = "#8957e5"
  const stateColor = (p) => {
    const t = api.theme.current
    if (p.state === "merged") return MERGED
    if (p.state === "closed") return t.error
    if (p.state === "draft") return t.textMuted
    return t.success
  }

  // The slot host inserts whatever this returns from inside a tracked effect.
  // Returning the Show (a reactive function) directly would let pr() changes
  // re-run that effect, which recreates this component and loops forever; a
  // static box keeps the reactivity inside.
  const root = createElement("box")
  insert(root, createComponent(Show, {
    get when() {
      return pr()
    },
    keyed: true,
    children: (p) => {
      const row = createElement("box")
      setProp(row, "flexDirection", "row")
      setProp(row, "gap", 1)
      if (p.branch) {
        const name = createElement("text")
        setProp(name, "wrapMode", "none")
        insert(name, p.branch.length > 28 ? p.branch.slice(0, 27) + "…" : p.branch)
        effect((prev) => setProp(name, "fg", api.theme.current.textMuted, prev))
        insertNode(row, name)
      }
      const text = createElement("text")
      setProp(text, "wrapMode", "none")
      setProp(text, "onMouseUp", () => void run("open", [p.url]).catch(() => {}))
      insert(text, `#${p.number}`)
      effect((prev) => setProp(text, "fg", stateColor(p), prev))
      insertNode(row, text)
      return row
    },
  }))
  return root
}

const tui = async (api, rawOptions) => {
  if (typeof api.slots?.register !== "function") return
  const options = { ...DEFAULTS, ...(rawOptions ?? {}) }
  api.slots.register({
    order: 100,
    slots: {
      session_prompt_footer(_ctx, props) {
        return createComponent(PrFooter, {
          api,
          options,
          get sessionID() {
            return props.session_id
          },
        })
      },
    },
  })
}

export default { id: "pr-footer", tui }
